// Temperature-dependent dielectric function ε(E,T) of TMDC monolayers
// (MoS₂, MoSe₂, WS₂) via the DFPM / PSEMI parametric oscillator model.
//
// Faithful TypeScript port of the `tmdc_dielectric` Python library:
//   each critical point is a 4-segment polynomial spline (the joint DOS),
//   convolved with a Kramers-Kronig-consistent complex Gaussian. On a real
//   energy grid the Faddeeva kernel reduces to plain Gaussians (ε₂) and the
//   Dawson function (ε₁), so no complex error function is needed.
// Parameter tables transcribed verbatim from the source papers (see `ref`).
// Validated against the Python library to < 2×10⁻⁴ over MoS₂/MoSe₂/WS₂.
//
// Sources:
//   MoS₂  — V. L. Le et al., Curr. Appl. Phys. 19 (2019) 182.
//   MoSe₂ — Le/Kim group (MoSe2.pdf).
//   WS₂   — T. J. Kim et al., J. Korean Phys. Soc. 77 (2020) 298.
//   Model — Johs & Herzinger, Thin Solid Films 313–314 (1998) 137 (PSEMI/DFPM).

export interface TmdcData {
  name: string; ref: string; Erange: number[]; Trange: number[];
  cpNames: string[]; CP_INDEX: number[]; CL: number[]; CU: number[]; M: number[];
  EC: number[][]; A: number[][]; B: number[][];
  ELM: number[][]; ALM: number[][]; EUM: number[][]; AUM: number[][];
  poleE: number[]; poleA: number[][];
}

